// ── Projected ledger constants (from lg:LEDGER_CONSTANTS) ────────────


/// hard cap on account count in one LedgerState
pub const MAX_ACCOUNTS: usize = 65536;

/// state root width in bytes
pub const STATE_ROOT_LEN: usize = 32;

/// per-transition gas placeholder (0 = counted, never charged)
pub const TRANSITION_GAS: usize = 0;


use std::collections::{BTreeMap, BTreeSet};

/// 32-byte account identifier (S1 strata-hash digest width).
pub type AccountId = [u8; 32];

/// State-root width fixture: the projected STATE_ROOT_LEN.
pub type Root = [u8; STATE_ROOT_LEN as usize];

/// One account (ontology class st:Account).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Account {
    pub id: AccountId,
    pub balance: u128,
}

/// TxLike: minimal local tx shape this ledger consumes. S2-shaped after the
/// strata-tx-pack Tx (replay-guard nonce + inputs/outputs; provenance:
/// packs/strata-tx-pack/templates/tx_model.rs.tera, roadmap slice S2). This
/// is a documentation-only shape mirror — no cross-pack dependency
/// (FM-PACK-018).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TxLike {
    /// Per-account replay-guard nonce (strata-tx-pack TX nonce convention).
    pub nonce: u64,
    /// Consumed side: (account id, amount) pairs.
    pub inputs: Vec<(AccountId, u128)>,
    /// Produced side: (account id, amount) pairs.
    pub outputs: Vec<(AccountId, u128)>,
    /// 32-byte digest of the exact tx bytes (replay court key).
    pub digest: [u8; 32],
}

/// Refusal valve: the explicit refusal type mirroring the PN64/valve pattern
/// (roadmap S4: "double-spend refusal via valve"). Zero-denial-admitted
/// polarity: `admitted()` is true only for the zero case — there is no
/// Ok-with-reservations arm; every non-admission is a typed refusal.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LedgerRefusal {
    /// A per-account nonce was reused (double spend; also covers replay of
    /// the same nonce).
    DoubleSpend,
    /// The exact tx digest was already applied (replay).
    Replay,
    /// Amount arithmetic would overflow u128.
    Overflow,
    /// Sum(inputs) != sum(outputs): value would be created or destroyed.
    Conservation,
    /// Applying the transition would exceed MAX_ACCOUNTS.
    CapacityExceeded,
    /// A debit exceeded the account's balance.
    InsufficientFunds,
}

impl LedgerRefusal {
    /// Zero-denial-admitted polarity: refusals are nonzero by construction;
    /// the admitted (zero) case is `Ok(..)`, never a refusal value.
    pub fn code(&self) -> u64 {
        match *self {
            LedgerRefusal::DoubleSpend => 1,
            LedgerRefusal::Replay => 2,
            LedgerRefusal::Overflow => 3,
            LedgerRefusal::Conservation => 4,
            LedgerRefusal::CapacityExceeded => 5,
            LedgerRefusal::InsufficientFunds => 6,
        }
    }
}

/// Receipt of one applied transition (ontology class st:TransitionReceipt).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StateTransitionReceipt {
    /// Monotonic transition index (st:transitionIndex).
    pub index: u64,
    /// State root before the commit (st:prevStateRoot).
    pub prev_root: Root,
    /// State root after the commit (st:stateRoot).
    pub next_root: Root,
    /// Digest of the committed tx (st:appliedTxDigest).
    pub applied_tx_digest: [u8; 32],
}

// ── PN64 normative model (ontology individuals lg:PN64_MODEL et al.) ────
/// The only event type the PN64 model admits as a synchronous move.
pub const OCEL_EVENT_TYPE_APPLY: &str = "apply_transition";
/// GALL-lifecycle projection of the apply event (st:gallEventType): the
/// beam4pm GallOcel vocabulary name this event admits into, without renaming
/// the model transition (`OCEL_EVENT_TYPE_APPLY` is unchanged).
pub const GALL_EVENT_TYPE_APPLY: &str = "candidate_committed";
/// Model transitions (single-transition normative model).
pub const PN64_TRANSITIONS: &[&str] = &["apply_transition"];
/// Model places.
pub const PN64_PLACES: &[&str] = &["p_ready", "p_settled"];
/// Input arcs (place, transition).
pub const PN64_INPUT_ARCS: &[(&str, &str)] = &[("p_ready", "apply_transition")];
/// Output arcs (transition, place) — self-reproducing: every firing
/// re-tokenizes p_ready, so any length of apply_transition log stays enabled.
pub const PN64_OUTPUT_ARCS: &[(&str, &str)] = &[
    ("apply_transition", "p_settled"),
    ("apply_transition", "p_ready"),
];
/// Initial marking (place, tokens).
pub const PN64_INITIAL_MARKING: &[(&str, u32)] = &[("p_ready", 1)];

/// One OCEL-v2 event emitted by an applied transition (ontology class
/// st:OcelEvent).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OcelEvent {
    /// OCEL-v2 event type = the emitting transition's name.
    pub event_type: String,
    /// GALL-lifecycle projection (st:gallEventType): GALL_EVENT_TYPE_APPLY.
    pub gall_event_type: String,
    /// OCEL-v2 timestamp = the emitting transition's index.
    pub timestamp: u64,
    /// Accounts touched (inputs ∪ outputs, deduplicated, sorted).
    pub objects: Vec<AccountId>,
}

/// Conformance report from `verify_conformance` (wasm4pm-style alignment
/// move counts; aligned iff total cost is 0).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ConformanceReport {
    /// True iff every event was a synchronous move (total alignment cost 0).
    pub aligned: bool,
    /// Total alignment cost: sync = 0, log/model move = 1 each.
    pub total_cost: u64,
    /// Synchronous moves (event type matched a model transition, enabled).
    pub sync_moves: usize,
    /// Log moves (event type matches no model transition — a fabricated
    /// event).
    pub log_moves: usize,
    /// Model moves (event type exists but the marking did not enable it).
    pub model_moves: usize,
    /// Timestamp of the first non-synchronous move, if any.
    pub first_violation: Option<u64>,
}

/// Account-based ledger state (ontology class st:LedgerState).
#[derive(Debug, Clone, Default)]
pub struct LedgerState {
    accounts: BTreeMap<AccountId, u128>,
    /// Last accepted nonce per (input) account.
    nonces: BTreeMap<AccountId, u64>,
    /// Applied tx digests (replay court).
    seen: BTreeSet<[u8; 32]>,
    /// OCEL-v2 event log: one event per applied transition (emission law).
    events: Vec<OcelEvent>,
    root: Root,
    index: u64,
}

impl LedgerState {
    pub fn new() -> LedgerState {
        LedgerState {
            accounts: BTreeMap::new(),
            nonces: BTreeMap::new(),
            seen: BTreeSet::new(),
            events: Vec::new(),
            root: [0u8; STATE_ROOT_LEN as usize],
            index: 0,
        }
    }

    /// Genesis allocation: pre-transition account seeding (documented
    /// genesis/airdrop surface, outside the transition law — the transition
    /// law itself never creates or destroys value). The genesis root becomes
    /// the base of the receipt chain.
    pub fn with_genesis(alloc: &[(AccountId, u128)]) -> LedgerState {
        let mut st = LedgerState::new();
        for &(id, bal) in alloc.iter() {
            st.accounts.insert(id, bal);
        }
        st.recompute_root();
        st
    }

    pub fn root(&self) -> Root {
        self.root
    }

    pub fn balance(&self, id: &AccountId) -> u128 {
        match self.accounts.get(id) {
            Some(b) => *b,
            None => 0,
        }
    }

    pub fn account_count(&self) -> usize {
        self.accounts.len()
    }

    pub fn index(&self) -> u64 {
        self.index
    }

    /// The OCEL-v2 event log (one event per applied transition).
    pub fn events(&self) -> &[OcelEvent] {
        &self.events
    }

    /// Court injection surface: record an externally supplied event so the
    /// conformance checker can be proven non-vacuous (a fabricated event must
    /// be injectable to witness the refusal). Production logs never call this.
    pub fn inject_event(&mut self, ev: OcelEvent) {
        self.events.push(ev);
    }

    /// wasm4pm-style alignment conformance (PROVENANCE ONLY — no code
    /// vendored; /Users/sac/wasm4pm/wasm4pm/src/alignments.rs): replay the
    /// OCEL event log against the PN64 normative model. Each event is a
    /// synchronous move (cost 0) iff its type names a model transition that
    /// the current marking enables; an event type matching no model
    /// transition is a log move (cost 1, fabricated event); an enabled-type
    /// event with a dry marking is a model move (cost 1). The log conforms
    /// iff total cost is 0. Emission law is checked alongside: each event's
    /// timestamp must equal its position (timestamp = transition index).
    pub fn verify_conformance(&self) -> ConformanceReport {
        // Initial marking.
        let mut marking: Vec<u32> = PN64_PLACES
            .iter()
            .map(|p| {
                PN64_INITIAL_MARKING
                    .iter()
                    .find(|mp| mp.0 == *p)
                    .map(|mp| mp.1)
                    .unwrap_or(0)
            })
            .collect();
        let mut report = ConformanceReport {
            aligned: true,
            total_cost: 0,
            sync_moves: 0,
            log_moves: 0,
            model_moves: 0,
            first_violation: None,
        };
        for (pos, ev) in self.events.iter().enumerate() {
            // Emission law: timestamp = transition index = position + 1
            // (indices are 1-based; the first applied transition is index 1).
            if ev.timestamp != (pos as u64) + 1 && report.first_violation.is_none() {
                report.first_violation = Some(ev.timestamp);
            }
            let t_idx = PN64_TRANSITIONS.iter().position(|t| *t == ev.event_type);
            match t_idx {
                None => {
                    // Log move: fabricated event type.
                    report.log_moves = report.log_moves + 1;
                }
                Some(ti) => {
                    let name = PN64_TRANSITIONS[ti];
                    let enabled = PN64_INPUT_ARCS.iter().all(|&(place, t)| {
                        if t != name {
                            return true;
                        }
                        let pi = PN64_PLACES.iter().position(|p| *p == place).unwrap();
                        marking[pi] >= 1
                    });
                    if enabled {
                        // Synchronous move: consume inputs, produce outputs.
                        for &(place, t) in PN64_INPUT_ARCS.iter() {
                            if t == name {
                                let pi = PN64_PLACES.iter().position(|p| *p == place).unwrap();
                                marking[pi] = marking[pi] - 1;
                            }
                        }
                        for &(t, place) in PN64_OUTPUT_ARCS.iter() {
                            if t == name {
                                let pi = PN64_PLACES.iter().position(|p| *p == place).unwrap();
                                marking[pi] = marking[pi] + 1;
                            }
                        }
                        report.sync_moves = report.sync_moves + 1;
                    } else {
                        // Model move: type exists, marking dry.
                        report.model_moves = report.model_moves + 1;
                    }
                }
            }
            if report.log_moves + report.model_moves > 0 && report.first_violation.is_none() {
                report.first_violation = Some(ev.timestamp);
            }
        }
        report.total_cost = (report.log_moves + report.model_moves) as u64;
        report.aligned = report.total_cost == 0 && report.first_violation.is_none();
        report
    }

    /// Deterministic placeholder state root (FNV-1a mixing over the sorted
    /// account set + index; strata-tx-pack placeholder convention until S1
    /// binds the real hash). Equal states derive equal roots.
    fn recompute_root(&mut self) {
        let mut h: u64 = 0xcbf29ce484222325;
        let mut mix = |b: u8, h: &mut u64| {
            *h = (*h ^ b as u64).wrapping_mul(0x100000001b3);
        };
        for (id, bal) in self.accounts.iter() {
            for i in 0..32 {
                mix(id[i], &mut h);
            }
            let mut b = *bal;
            let mut k = 0;
            while k < 16 {
                mix((b & 0xff) as u8, &mut h);
                b = b >> 8;
                k = k + 1;
            }
        }
        let mut idx = self.index;
        let mut k = 0;
        while k < 8 {
            mix((idx & 0xff) as u8, &mut h);
            idx = idx >> 8;
            k = k + 1;
        }
        let mut root = [0u8; STATE_ROOT_LEN as usize];
        let mut i = 0;
        while i < STATE_ROOT_LEN as usize {
            root[i] = ((h >> ((i % 8) * 8)) & 0xff) as u8;
            i = i + 1;
        }
        self.root = root;
    }

    /// Masked commit: apply one transition all-or-nothing. Every gate
    /// (replay, nonce, overflow, conservation, capacity, funds) runs BEFORE
    /// any balance mutates; on refusal the state is bit-identical to the
    /// input. On admission, receipts the prior root (receipt chaining).
    pub fn apply_transition(
        &mut self,
        tx: &TxLike,
    ) -> Result<StateTransitionReceipt, LedgerRefusal> {
        let prev_root = self.root;

        // Gate 1: replay valve.
        if self.seen.contains(&tx.digest) {
            return Err(LedgerRefusal::Replay);
        }

        // Gate 2: double-spend valve — every input account must advance its
        // nonce strictly (nonce reuse per account is refused).
        for &(id, _) in tx.inputs.iter() {
            let last = match self.nonces.get(&id) {
                Some(n) => *n,
                None => 0,
            };
            if tx.nonce == 0 || tx.nonce <= last {
                return Err(LedgerRefusal::DoubleSpend);
            }
        }

        // Gate 3: overflow + conservation over the masked sums.
        let mut sum_in: u128 = 0;
        for &(_, amt) in tx.inputs.iter() {
            sum_in = match sum_in.checked_add(amt) {
                Some(s) => s,
                None => return Err(LedgerRefusal::Overflow),
            };
        }
        let mut sum_out: u128 = 0;
        for &(_, amt) in tx.outputs.iter() {
            sum_out = match sum_out.checked_add(amt) {
                Some(s) => s,
                None => return Err(LedgerRefusal::Overflow),
            };
        }
        if sum_in != sum_out {
            return Err(LedgerRefusal::Conservation);
        }

        // Gate 4: funds + capacity, checked against a shadow copy (masked:
        // nothing here mutates self).
        //
        // DUPLICATE-INPUT DEBIT ACCUMULATION LAW: same-account input rows are
        // ACCUMULATED into one per-account debit, applied once against the
        // original balance. Reading the original balance per row and
        // overwriting the shadow slot (the previous projection) silently
        // dropped every deduction but the last: with inputs [(acct0,5),
        // (acct0,5)] and outputs [(acct1,10)] all four gates passed while 5
        // units were minted from nothing (Lean counterexample, mfact
        // procint/ProcInt/Petri/LedgerConservation.lean @ main). Accumulating
        // deltas makes Σ(conservation) hold unconditionally over every
        // gate-passing tx, with no NoDupIds precondition on tx inputs.
        let mut debits: BTreeMap<AccountId, u128> = BTreeMap::new();
        for &(id, amt) in tx.inputs.iter() {
            let cur_debit = match debits.get(&id) {
                Some(d) => *d,
                None => 0,
            };
            let total = match cur_debit.checked_add(amt) {
                Some(v) => v,
                None => return Err(LedgerRefusal::Overflow),
            };
            debits.insert(id, total);
        }
        let mut shadow: BTreeMap<AccountId, u128> = BTreeMap::new();
        for (id, debit) in debits.iter() {
            let cur = self.balance(id);
            if cur < *debit {
                return Err(LedgerRefusal::InsufficientFunds);
            }
            shadow.insert(*id, cur - *debit);
        }
        for &(id, amt) in tx.outputs.iter() {
            let cur = match shadow.get(&id) {
                Some(b) => *b,
                None => self.balance(&id),
            };
            let next = match cur.checked_add(amt) {
                Some(v) => v,
                None => return Err(LedgerRefusal::Overflow),
            };
            shadow.insert(id, next);
        }
        let mut new_accounts = 0usize;
        for &id in shadow.keys() {
            if !self.accounts.contains_key(&id) {
                new_accounts = new_accounts + 1;
            }
        }
        if self.accounts.len() + new_accounts > MAX_ACCOUNTS as usize {
            return Err(LedgerRefusal::CapacityExceeded);
        }

        // ── Commit (masked: reached only when every gate passed) ────────
        for (id, bal) in shadow.into_iter() {
            if bal == 0 && tx.outputs.iter().find(|&&(oid, _)| oid == id).is_none() {
                self.accounts.remove(&id);
            } else {
                self.accounts.insert(id, bal);
            }
        }
        for &(id, _) in tx.inputs.iter() {
            self.nonces.insert(id, tx.nonce);
        }
        self.seen.insert(tx.digest);
        self.index = self.index + 1;
        self.recompute_root();

        // OCEL-v2 emission (one event per applied transition): event type =
        // transition name, timestamp = transition index, objects = accounts
        // touched (inputs ∪ outputs, deduplicated, sorted).
        let mut objects: Vec<AccountId> = Vec::new();
        for &(id, _) in tx.inputs.iter() {
            if !objects.contains(&id) {
                objects.push(id);
            }
        }
        for &(id, _) in tx.outputs.iter() {
            if !objects.contains(&id) {
                objects.push(id);
            }
        }
        objects.sort();
        self.events.push(OcelEvent {
            event_type: OCEL_EVENT_TYPE_APPLY.to_string(),
            gall_event_type: GALL_EVENT_TYPE_APPLY.to_string(),
            timestamp: self.index,
            objects: objects,
        });

        Ok(StateTransitionReceipt {
            index: self.index,
            prev_root: prev_root,
            next_root: self.root,
            applied_tx_digest: tx.digest,
        })
    }

    /// Receipt-chain law (unibit verify_receipt_chain projection): each
    /// receipt's prev_root must equal the prior state root it replaced —
    /// i.e. receipt[i].prev_root == receipt[i-1].next_root, receipt[0]
    /// .prev_root == the genesis root, and index strictly increases.
    pub fn verify_receipt_chain(
        genesis_root: &Root,
        receipts: &[StateTransitionReceipt],
    ) -> bool {
        let mut prev = *genesis_root;
        let mut last_index: u64 = 0;
        let mut first = true;
        for rc in receipts.iter() {
            if rc.prev_root != prev {
                return false;
            }
            if !first && rc.index <= last_index {
                return false;
            }
            first = false;
            last_index = rc.index;
            prev = rc.next_root;
        }
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn id(n: u8) -> AccountId {
        let mut a = [0u8; 32];
        a[0] = n;
        a
    }

    fn mk_tx(nonce: u64, digest: [u8; 32], ios: &[(AccountId, u128, u128)]) -> TxLike {
        let mut inputs = Vec::new();
        let mut outputs = Vec::new();
        for &(acct, amt_in, amt_out) in ios.iter() {
            if amt_in > 0 {
                inputs.push((acct, amt_in));
            }
            if amt_out > 0 {
                outputs.push((acct, amt_out));
            }
        }
        TxLike {
            nonce: nonce,
            inputs: inputs,
            outputs: outputs,
            digest: digest,
        }
    }

    #[test]
    fn lean_counterexample_duplicate_input_refused() {
        // Regression court (L107): the exact mfact Lean counterexample —
        // inputs [(acct0,5),(acct0,5)], outputs [(acct1,10)] — previously
        // passed all four gates and minted 5 units from nothing via the
        // shadow-map row overwrite. It must now be refused (typed) with the
        // state bit-identical, and the debit-accumulated form must admit with
        // Σ conserved.
        let a = id(1);
        let b = id(2);
        // Case 1: acct0 holds only 5 — the duplicate input must refuse.
        let mut st = LedgerState::with_genesis(&[(a, 5u128)]);
        let root_before = st.root();
        let mut d = [0u8; 32];
        d[0] = 21;
        let mut inputs = Vec::new();
        inputs.push((a, 5u128));
        inputs.push((a, 5u128));
        let mut outputs = Vec::new();
        outputs.push((b, 10u128));
        let tx = TxLike { nonce: 1, inputs: inputs, outputs: outputs, digest: d };
        let r = st.apply_transition(&tx);
        assert_eq!(r, Err(LedgerRefusal::InsufficientFunds));
        assert_eq!(st.root(), root_before);
        assert_eq!(st.balance(&a), 5);
        assert_eq!(st.balance(&b), 0);
        assert_eq!(st.events().len(), 0);
        // Case 2: acct0 holds 10 — same shape now admits with exact
        // accumulation (a=0 removed, b=10), Σ conserved, not a=5 leaked.
        let mut st2 = LedgerState::with_genesis(&[(a, 10u128)]);
        let root2_before = st2.root();
        let mut d2 = [0u8; 32];
        d2[0] = 22;
        let mut inputs2 = Vec::new();
        inputs2.push((a, 5u128));
        inputs2.push((a, 5u128));
        let mut outputs2 = Vec::new();
        outputs2.push((b, 10u128));
        let tx2 = TxLike { nonce: 1, inputs: inputs2, outputs: outputs2, digest: d2 };
        let rc = st2.apply_transition(&tx2).ok().unwrap();
        assert_eq!(rc.prev_root, root2_before);
        assert_eq!(st2.balance(&a), 0);
        assert_eq!(st2.balance(&b), 10);
        assert_eq!(st2.events().len(), 1);
    }

    #[test]
    fn conservation_property_500_txs_with_duplicate_inputs() {
        // Property court (L107): 500 deterministic txs including same-account
        // multi-input rows. For every admitted tx, post-apply Σ over all
        // accounts == pre-apply Σ; every refused tx leaves the state root
        // bit-identical.
        let mut seed: u64 = 0x9E3779B97F4A7C15;
        let a = id(1);
        let b = id(2);
        let c = id(3);
        let mut st = LedgerState::with_genesis(&[
            (a, 1_000_000u128),
            (b, 400_000u128),
            (c, 600_000u128),
        ]);
        let supply = 2_000_000u128;
        let mut n = 0u64;
        while n < 500 {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let amt: u128 = ((seed >> 40) % 300) as u128 + 1;
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let pick = (seed >> 33) % 3;
            let src = match pick { 0 => a, 1 => b, _ => c };
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let dst = match ((seed >> 33) % 3) { 0 => a, 1 => b, _ => c };
            // Split the debit into 1-3 duplicate rows on the same account.
            let rows = (amt % 3) + 1;
            let part = amt / rows;
            let mut inputs = Vec::new();
            let mut i: u128 = 0;
            while i < rows {
                inputs.push((src, part));
                i = i + 1;
            }
            // Top the last row up so Σ(inputs) == amt exactly.
            let used = part * rows;
            if used < amt {
                let last_idx = inputs.len() - 1;
                let last = inputs[last_idx];
                inputs[last_idx] = (last.0, last.1 + (amt - used));
            }
            let mut outputs = Vec::new();
            outputs.push((dst, amt));
            let mut d = [0u8; 32];
            d[0] = 23;
            let base: [u8; 8] = [
                (n & 0xff) as u8,
                ((n >> 8) & 0xff) as u8,
                0, 0, 0, 0, 0, 0,
            ];
            let mut i = 0;
            while i < 8 {
                d[1 + i] = base[i];
                i = i + 1;
            }
            let root_before = st.root();
            let tx = TxLike {
                nonce: 9000 + n,
                inputs: inputs,
                outputs: outputs,
                digest: d,
            };
            let total_before = st.balance(&a) + st.balance(&b) + st.balance(&c);
            match st.apply_transition(&tx) {
                Ok(_) => {
                    let total_after = st.balance(&a) + st.balance(&b) + st.balance(&c);
                    assert_eq!(total_after, total_before);
                    assert_eq!(total_after, supply);
                }
                Err(_) => {
                    assert_eq!(st.root(), root_before);
                }
            }
            n = n + 1;
        }
    }

    #[test]
    fn conservation_holds_over_random_sequences() {
        // Deterministic LCG "random" sequence of conservation-preserving
        // transfers; total supply must be invariant after every commit.
        let mut seed: u64 = 0x243F6A8885A308D3;
        let a = id(1);
        let b = id(2);
        let c = id(3);
        // Genesis allocation (pre-transition; the transition law never
        // creates value).
        let mut st = LedgerState::with_genesis(&[
            (a, 1_000_000u128),
            (b, 400_000u128),
            (c, 600_000u128),
        ]);
        let genesis_root = st.root();
        let mut receipts = Vec::new();
        let supply = 2_000_000u128;
        let mut n = 0;
        while n < 200 {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let from = match (seed >> 33) % 3 {
                0 => a,
                1 => b,
                _ => c,
            };
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let to = match (seed >> 33) % 3 {
                0 => a,
                1 => b,
                _ => c,
            };
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let amt: u128 = (((seed >> 20) % 5_000) + 1) as u128;
            if from == to {
                continue;
            }
            if st.balance(&from) < amt {
                continue;
            }
            let mut d = [0u8; 32];
            d[0] = 7;
            let base: [u8; 8] = [
                (n & 0xff) as u8,
                ((n >> 8) & 0xff) as u8,
                0, 0, 0, 0, 0, 0,
            ];
            let mut i = 0;
            while i < 8 {
                d[1 + i] = base[i];
                i = i + 1;
            }
            let tx = mk_tx(1000 + n as u64, d, &[(from, amt, 0), (to, 0, amt)]);
            let rc = st.apply_transition(&tx).ok().unwrap();
            receipts.push(rc);
            let total = st.balance(&a) + st.balance(&b) + st.balance(&c);
            assert_eq!(total, supply);
            n = n + 1;
        }
        assert!(LedgerState::verify_receipt_chain(&genesis_root, &receipts));
    }

    #[test]
    fn double_spend_refused() {
        let mut st = LedgerState::with_genesis(&[(id(1), 1_000u128)]);
        let a = id(1);
        let b = id(2);
        assert!(st.apply_transition(&mk_tx(5, [1u8; 32], &[(a, 500u128, 0), (b, 0, 500)])).is_ok());
        // Reuse account A's nonce 5 → DoubleSpend, state untouched.
        let r = st.apply_transition(&mk_tx(5, [2u8; 32], &[(a, 500u128, 0), (b, 0, 500)]));
        assert_eq!(r, Err(LedgerRefusal::DoubleSpend));
        // Nonce must strictly advance: going backwards also refuses.
        let r2 = st.apply_transition(&mk_tx(3, [3u8; 32], &[(a, 500u128, 0), (b, 0, 500)]));
        assert_eq!(r2, Err(LedgerRefusal::DoubleSpend));
        // Refusal is masked: state bit-identical (a=500, b=500 unchanged).
        assert_eq!(st.balance(&a), 500);
        assert_eq!(st.balance(&b), 500);
    }

    #[test]
    fn overflow_refused() {
        let mut st = LedgerState::with_genesis(&[
            (id(2), u128::MAX - 9u128),
            (id(3), 10u128),
        ]);
        let a = id(1);
        let b = id(2);
        let c = id(3);
        // B (MAX-10) + 10 credits C's 10 via a transfer that routes through B.
        let r = st.apply_transition(&mk_tx(2, [2u8; 32], &[
            (c, 10u128, 0),
            (b, 0, 10),
        ]));
        // B receives 10 while holding MAX-10 → output-side overflow.
        assert_eq!(r, Err(LedgerRefusal::Overflow));
    }

    #[test]
    fn replay_refused() {
        let mut st = LedgerState::with_genesis(&[(id(1), 100u128)]);
        let a = id(1);
        let b = id(2);
        let tx = mk_tx(1, [4u8; 32], &[(a, 100u128, 0), (b, 0, 100)]);
        assert!(st.apply_transition(&tx).is_ok());
        // Byte-identical tx re-submitted (fresh state copy semantics would
        // admit it; the seen-digest valve refuses).
        let r = st.apply_transition(&tx);
        assert_eq!(r, Err(LedgerRefusal::Replay));
    }

    #[test]
    fn receipt_chain_verifies() {
        let mut st = LedgerState::with_genesis(&[(id(1), 1_000_000u128)]);
        let genesis = st.root();
        let a = id(1);
        let b = id(2);
        let mut receipts = Vec::new();
        let mut n = 0u64;
        while n < 10 {
            let mut d = [0u8; 32];
            d[0] = 8;
            d[1] = n as u8;
            let tx = mk_tx(
                n + 1,
                d,
                &[(a, (n as u128 + 1u128) * 100u128, 0), (b, 0, (n as u128 + 1u128) * 100u128)],
            );
            receipts.push(st.apply_transition(&tx).ok().unwrap());
            n = n + 1;
        }
        // Chaining law: each receipt's prev_root == prior state root.
        assert!(LedgerState::verify_receipt_chain(&genesis, &receipts));
        // Negative witness: a corrupted receipt breaks the chain.
        let mut broken = receipts.clone();
        broken[3].prev_root = [9u8; STATE_ROOT_LEN as usize];
        assert!(!LedgerState::verify_receipt_chain(&genesis, &broken));
        // Positive control: empty chain over genesis trivially verifies.
        assert!(LedgerState::verify_receipt_chain(&genesis, &[]));
    }

    #[test]
    fn conservation_refusal_masks_state() {
        // Value creation is refused and the state is bit-identical after.
        let mut st = LedgerState::with_genesis(&[(id(1), 1_000u128), (id(2), 1_000u128)]);
        let a = id(1);
        let b = id(2);
        let root_before = st.root();
        // Outputs create 1 unit out of nothing.
        let r = st.apply_transition(&mk_tx(2, [2u8; 32], &[
            (a, 1_000u128, 0),
            (b, 0, 1_001),
        ]));
        assert_eq!(r, Err(LedgerRefusal::Conservation));
        assert_eq!(st.root(), root_before);
        // The valid successor still lands with the correct chaining shape.
        let ok = st.apply_transition(&mk_tx(2, [3u8; 32], &[
            (a, 1_000u128, 0),
            (b, 0, 1_000),
        ])).ok().unwrap();
        assert_eq!(ok.prev_root, root_before);
    }

    #[test]
    fn ocel_emit_then_verify_round_trip_200() {
        // 200 transitions: after every commit exactly one OCEL event exists,
        // with type = transition name, timestamp = transition index, and
        // objects = the accounts that transition actually touched. Then the
        // full log must conform (cost 0, all synchronous moves).
        let mut seed: u64 = 0x243F6A8885A308D3;
        let a = id(1);
        let b = id(2);
        let c = id(3);
        let mut st = LedgerState::with_genesis(&[
            (a, 1_000_000u128),
            (b, 400_000u128),
            (c, 600_000u128),
        ]);
        let mut n = 0;
        while n < 200 {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let from = match (seed >> 33) % 3 {
                0 => a,
                1 => b,
                _ => c,
            };
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let to = match (seed >> 33) % 3 {
                0 => a,
                1 => b,
                _ => c,
            };
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let amt: u128 = (((seed >> 20) % 5_000) + 1) as u128;
            if from == to {
                continue;
            }
            if st.balance(&from) < amt {
                continue;
            }
            let mut d = [0u8; 32];
            d[0] = 11;
            let base: [u8; 8] = [
                (n & 0xff) as u8,
                ((n >> 8) & 0xff) as u8,
                0, 0, 0, 0, 0, 0,
            ];
            let mut i = 0;
            while i < 8 {
                d[1 + i] = base[i];
                i = i + 1;
            }
            let expect_touched: BTreeSet<AccountId> = {
                let mut s = BTreeSet::new();
                s.insert(from);
                s.insert(to);
                s
            };
            let rc = st.apply_transition(&mk_tx(
                7000 + n as u64,
                d,
                &[(from, amt, 0), (to, 0, amt)],
            )).ok().unwrap();
            // Emission law: exactly one event per applied transition.
            assert_eq!(st.events().len(), rc.index as usize);
            let ev = &st.events()[rc.index as usize - 1];
            assert_eq!(ev.event_type, "apply_transition");
            assert_eq!(ev.timestamp, rc.index);
            let got: BTreeSet<AccountId> = ev.objects.iter().cloned().collect();
            assert_eq!(got, expect_touched);
            n = n + 1;
        }
        assert_eq!(st.events().len(), 200);
        let rep = st.verify_conformance();
        assert!(rep.aligned);
        assert_eq!(rep.total_cost, 0);
        assert_eq!(rep.sync_moves, 200);
        assert_eq!(rep.log_moves, 0);
        assert_eq!(rep.model_moves, 0);
        assert_eq!(rep.first_violation, None);
    }

    #[test]
    fn conformance_refuses_fabricated_transition() {
        let mut st = LedgerState::with_genesis(&[(id(1), 1_000u128)]);
        let a = id(1);
        let b = id(2);
        let mut n = 0u64;
        while n < 3 {
            let mut d = [0u8; 32];
            d[0] = 12;
            d[1] = n as u8;
            st.apply_transition(&mk_tx(
                n + 1,
                d,
                &[(a, 100u128, 0), (b, 0, 100u128)],
            )).ok().unwrap();
            n = n + 1;
        }
        // Positive control: the genuine log conforms.
        let rep = st.verify_conformance();
        assert!(rep.aligned);
        assert_eq!(rep.sync_moves, 3);
        // Inject a fabricated event: a transition name the PN64 model does
        // not know. It must surface as a log move — a refusal, not a pass.
        st.inject_event(OcelEvent {
            event_type: "fabricated_transition".to_string(),
            gall_event_type: "fabricated_transition".to_string(),
            timestamp: 3,
            objects: vec![a],
        });
        let rep2 = st.verify_conformance();
        assert!(!rep2.aligned);
        assert_eq!(rep2.log_moves, 1);
        assert_eq!(rep2.total_cost, 1);
        assert_eq!(rep2.first_violation, Some(3));
        // A desynchronized timestamp (emission-law violation) also refuses.
        let mut st2 = LedgerState::with_genesis(&[(id(1), 1_000u128)]);
        let mut d = [0u8; 32];
        d[0] = 13;
        st2.apply_transition(&mk_tx(1, d, &[(a, 100u128, 0), (b, 0, 100u128)])).ok().unwrap();
        st2.inject_event(OcelEvent {
            event_type: "apply_transition".to_string(),
            gall_event_type: GALL_EVENT_TYPE_APPLY.to_string(),
            timestamp: 9,
            objects: vec![a],
        });
        let rep3 = st2.verify_conformance();
        assert!(!rep3.aligned);
        assert_eq!(rep3.first_violation, Some(9));
    }

    /// Sabotage twin — mutate-before-check: the same gate sequence as
    /// `apply_transition` except the conservation check runs AFTER the
    /// shadow commit, so a conservation-violating tx debits the sender and
    /// mints the receiver's balance before refusing.
    fn apply_transition_mutate_first(
        st: &mut LedgerState,
        tx: &TxLike,
    ) -> Result<StateTransitionReceipt, LedgerRefusal> {
        // Gate 1: replay valve (kept).
        if st.seen.contains(&tx.digest) {
            return Err(LedgerRefusal::Replay);
        }
        // Gate 2: double-spend valve (kept).
        for &(acct, _) in tx.inputs.iter() {
            let last = match st.nonces.get(&acct) {
                Some(n) => *n,
                None => 0,
            };
            if tx.nonce == 0 || tx.nonce <= last {
                return Err(LedgerRefusal::DoubleSpend);
            }
        }
        // Gate 3: overflow sums (kept) — but NO conservation refusal here.
        let mut sum_in: u128 = 0;
        for &(_, amt) in tx.inputs.iter() {
            sum_in = match sum_in.checked_add(amt) {
                Some(s) => s,
                None => return Err(LedgerRefusal::Overflow),
            };
        }
        let mut sum_out: u128 = 0;
        for &(_, amt) in tx.outputs.iter() {
            sum_out = match sum_out.checked_add(amt) {
                Some(s) => s,
                None => return Err(LedgerRefusal::Overflow),
            };
        }
        // SABOTAGE: the shadow commit below runs BEFORE the conservation
        // check; the refusal (if any) fires on already-mutated state.
        let mut debits: BTreeMap<AccountId, u128> = BTreeMap::new();
        for &(acct, amt) in tx.inputs.iter() {
            let cur_debit = match debits.get(&acct) {
                Some(d) => *d,
                None => 0,
            };
            debits.insert(acct, cur_debit + amt);
        }
        let mut shadow: BTreeMap<AccountId, u128> = BTreeMap::new();
        for (acct, debit) in debits.iter() {
            let cur = st.balance(acct);
            if cur < *debit {
                return Err(LedgerRefusal::InsufficientFunds);
            }
            shadow.insert(*acct, cur - *debit);
        }
        for &(acct, amt) in tx.outputs.iter() {
            let cur = match shadow.get(&acct) {
                Some(b) => *b,
                None => st.balance(&acct),
            };
            shadow.insert(acct, cur + amt);
        }
        for (acct, bal) in shadow.into_iter() {
            if bal == 0 && tx.outputs.iter().find(|&&(oid, _)| oid == acct).is_none() {
                st.accounts.remove(&acct);
            } else {
                st.accounts.insert(acct, bal);
            }
        }
        for &(acct, _) in tx.inputs.iter() {
            st.nonces.insert(acct, tx.nonce);
        }
        st.seen.insert(tx.digest);
        st.index = st.index + 1;
        st.recompute_root();
        // Refusal fires only now — on mutated state, with no rollback.
        if sum_in != sum_out {
            return Err(LedgerRefusal::Conservation);
        }
        Err(LedgerRefusal::Replay) // unreachable: sabotage stub never admits
    }

    /// COURT — all-or-nothing: a conservation-violating tx must be refused
    /// with the state bit-identical to the input. The mutate-first twin is
    /// CAUGHT because its refusal leaves the ledger changed (sender debited,
    /// receiver minted).
    #[test]
    fn sabotage_twin_mutate_before_conservation_is_caught() {
        let a = id(1);
        let b = id(2);
        let mut honest = LedgerState::with_genesis(&[(a, 100u128)]);
        let mut sabotaged = LedgerState::with_genesis(&[(a, 100u128)]);
        // sum_in = 50, sum_out = 60: conservation violation, gates pass.
        let tx = mk_tx(1, [9u8; 32], &[(a, 50u128, 0), (a, 0, 50u128), (b, 0, 10u128)]);

        // Honest: typed refusal, state bit-identical to input.
        let before_root = honest.root();
        assert_eq!(
            honest.apply_transition(&tx),
            Err(LedgerRefusal::Conservation)
        );
        assert_eq!(honest.balance(&a), 100);
        assert_eq!(honest.balance(&b), 0);
        assert_eq!(honest.root(), before_root);
        assert_eq!(honest.index(), 0);

        // Twin: returns the same typed refusal but the ledger MUTATED —
        // caught by the all-or-nothing court.
        assert_eq!(
            apply_transition_mutate_first(&mut sabotaged, &tx),
            Err(LedgerRefusal::Conservation)
        );
        assert_eq!(sabotaged.balance(&a), 100, "sender row was committed before the check");
        assert_eq!(sabotaged.balance(&b), 10, "receiver was minted before the check");
        assert_eq!(sabotaged.index(), 1, "index advanced before the check");
        assert_ne!(
            sabotaged.root(),
            before_root,
            "root changed before the check — all-or-nothing broken"
        );
    }
}
